from toml_parser import parse_toml


def test_string_value():
    result = parse_toml('title = "My App"')
    assert result == {"title": "My App"}


def test_single_quoted_string():
    result = parse_toml("name = 'hello'")
    assert result == {"name": "hello"}


def test_integer_value():
    result = parse_toml("port = 8080")
    assert result == {"port": 8080}


def test_boolean():
    result = parse_toml("debug = true\nproduction = false")
    assert result == {"debug": True, "production": False}


def test_section():
    toml = '[server]\nport = 8080\nhost = "localhost"'
    result = parse_toml(toml)
    assert result == {"server": {"port": 8080, "host": "localhost"}}


def test_multiple_sections():
    toml = '[db]\nhost = "db1"\n\n[server]\nhost = "web1"'
    result = parse_toml(toml)
    assert result == {
        "db": {"host": "db1"},
        "server": {"host": "web1"},
    }


def test_top_level_and_section():
    toml = 'app = "api"\n\n[server]\nport = 3000'
    result = parse_toml(toml)
    assert result == {"app": "api", "server": {"port": 3000}}


def test_comments():
    toml = '# this is a comment\nkey = "value"\n# another comment'
    result = parse_toml(toml)
    assert result == {"key": "value"}


def test_inline_comment():
    toml = 'port = 8080  # server port'
    result = parse_toml(toml)
    assert result == {"port": 8080}


def test_array_of_integers():
    toml = 'ports = [8000, 8001, 8002]'
    result = parse_toml(toml)
    assert result == {"ports": [8000, 8001, 8002]}


def test_array_of_strings():
    toml = 'tags = ["web", "api", "v2"]'
    result = parse_toml(toml)
    assert result == {"tags": ["web", "api", "v2"]}


def test_empty_lines():
    toml = '\n\nkey = "value"\n\n\n'
    result = parse_toml(toml)
    assert result == {"key": "value"}


def test_empty_input():
    assert parse_toml("") == {}


def test_negative_integer():
    result = parse_toml("offset = -100")
    assert result == {"offset": -100}
